body:
{
  "id": "shotcut",
  "version": "schemaxis.shotcut/1",
  "adaptor": "schemaxis.adaptors.shotcut.adaptor",
  "declarations": "schemaxis.adaptors.shotcut.adaptor:DECLARATIONS",
  "runtimeFamily": "Shotcut bundled MLT 7.x",
  "executables": [
    "melt"
  ],
  "execution": "Named video assets and ordered frame ranges to an editable Shotcut MLT timeline and verified FFV1 render",
  "keywords": [
    "video",
    "editing",
    "timeline",
    "cuts",
    "Shotcut",
    "MLT"
  ],
  "executionCapabilities": {
    "modes": [
      "process"
    ],
    "nativeThreads": true,
    "mpi": false
  },
  "consoleTemplate": {
    "version": "schemaxis.shotcut/1",
    "nodes": []
  },
  "consoleCapabilities": {
    "authoredSessions": true,
    "multipleDocuments": true,
    "liveGeometry": false,
    "nativeEditReverseSync": false
  },
  "routes": {
    "schemaxis.shotcut/1": {
      "module": "schemaxis.adaptors.shotcut.adaptor",
      "schema": "schemaxis.adaptors.shotcut.adaptor:schema",
      "workflow": true,
      "scheduled": true,
      "compose": true,
      "schemaName": "shotcut",
      "acceptedArtifacts": [
        "video"
      ],
      "hooks": {
        "reusableInputs": "schemaxis.adaptors.shotcut.adaptor:reusableInputs",
        "resources": "schemaxis.adaptors.shotcut.adaptor:resources",
        "provisionalResources": "schemaxis.adaptors.shotcut.adaptor:provisionalResources"
      }
    }
  },
  "capabilities": "schemaxis.adaptors.shotcut.capabilities:catalogue",
  "studioCatalogue": "schemaxis.adaptors.shotcut.adaptor:studioCatalogue"
}
